const note = sticky("## CEO Brain — Training Dashboard (page)\nServes Ryan's training room at GET /webhook/ceo-brain/dashboard. The page talks to the Trainer API (POST /webhook/ceo-brain/trainer). Source of truth: repo ryan/ceo-brain/dashboard/index.html — rebuild with node dashboard/build.js and redeploy; never edit the HTML here.", [page, serve], { color: 4 });

export default workflow('ceo-brain-training-dashboard', 'CEO Brain — Training Dashboard')
  .add(page)
  .to(serve)
